queries.sql:
SELECT hex(s.name) name,COUNT(*) count,MIN(s.ts) first_ns,MAX(s.ts+s.dur) last_end_ns
FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t ON t.utid=tt.utid JOIN process p ON p.upid=t.upid
WHERE p.uid=10112 AND p.name='com.android.inputmethod.latin' AND (s.name GLOB 'IMS.*' OR s.name='clientTransactionExecuted' OR s.name='configChanged') GROUP BY s.name ORDER BY s.name;

SELECT s.id,s.parent_id,s.ts,s.dur,s.depth,s.track_id,hex(s.name) name
FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t ON t.utid=tt.utid JOIN process p ON p.upid=t.upid
WHERE p.uid=10112 AND p.name='com.android.inputmethod.latin' AND t.is_main_thread=1 AND s.ts>=47170000000 AND s.ts<47260000000 ORDER BY s.ts,s.id LIMIT 1000;
